changeSet.sql:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterUpsert] ON [dbo].[Field] FOR INSERT, UPDATE AS SET NOCOUNT ON;
-- formatted value logic only needs to run in cases where value is not null if exists( select 1 from inserted where [value] is not null or [formattedvalue] is not null) begin
if exists (select 1 from inserted where AssetID IS NOT NULL) begin UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and (F.AssetID IS NOT NULL AND F.AssetID = T.AssetID) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID; end
if exists (select 1 from inserted where IntersectID IS NOT NULL) begin UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and (F.IntersectID IS NOT NULL AND F.IntersectID = T.IntersectID) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID; end
if exists (select 1 from inserted where IssueID IS NOT NULL) begin UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and (F.IssueID IS NOT NULL AND F.IssueID = T.IssueID) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID; end
drop table if exists #insertedFields; create table #insertedFields (ObjectType varchar(250), ObjectID int); create clustered index IX_TempInsertedFields ON #insertedFields (ObjectType, ObjectID);
drop table if exists #distinctFieldTypeIDs; create table #distinctFieldTypeIDs (ID int); create clustered index IX_distinctFieldTypeIDs ON #distinctFieldTypeIDs (ID);
insert into #distinctFieldTypeIDs select distinct I.FieldTypeID from inserted i where exists (select 1 from deleted d where d.id = i.id);
insert into #insertedFields select distinct replace(AT.[Object],'Type',''), AT.ObjectID from #distinctFieldTypeIDs i inner join FieldType FT on FT.ID = i.ID inner join assettype AT on AT.ID = FT.AssetTypeID and FT.AssetTypeID is not Null union select 'Intersect', FT.IntersectTypeID from #distinctFieldTypeIDs i inner join FieldType FT on FT.ID = i.ID and FT.IntersectTypeID is not Null union select 'Issue', FT.IssueTypeID from #distinctFieldTypeIDs i inner join FieldType FT on FT.ID = i.ID and FT.IssueTypeID is not Null;
drop table if exists #lookupFieldTypes select distinct FT.ID into #lookupFieldTypes from #insertedFields SF inner join FieldType FT on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID
if exists( select top 1 1 from #lookupFieldTypes ) begin
UPDATE TF SET TF.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, TF.Value, FT.AllowMultipleValues) from Field TF inner join #lookupFieldTypes LFT ON LFT.ID = TF.FieldTypeID inner join FieldType FT on FT.ID = TF.FieldTypeID where TF.[Value] is not null; end end
-------------------------------------------- -- audit field value changes --------------------------------------------
drop table if exists #tempInserted; drop table if exists #tempDeleted;
select distinct AssetID, IntersectID, ID, UpdatedBy, cast('Add' as nvarchar(20)) ActionName into #tempInserted from inserted;
create clustered index cx_tempInserted on #tempInserted(AssetID,ID);
select distinct AssetID, IntersectID into #tempDeleted from DELETED;
declare @resourceId int = null;
if exists (select 1 from #tempInserted where AssetID is not null) begin
if (select count(distinct updatedby) from #tempInserted where AssetID is not null) > 1 begin set @resourceid = 0 end
drop table if exists #tempInsertedAsset;
select t.AssetID, Max(t.ActionName) ActionName, max(t.UpdatedBy) UpdatedBy into #tempInsertedAsset from #tempInserted t where t.AssetID is not null group by t.AssetID;
drop table if exists #tempFieldAssetID;
select t.AssetID into #tempFieldAssetID from #tempInsertedAsset t inner join Field F on F.AssetID = t.AssetID where F.AssetID is not null and not exists(select 1 from #tempInserted ti where ti.assetid = F.assetid and ti.id = F.id) group by t.AssetID;
update t set t.ActionName = 'Update' from #tempInsertedAsset t inner join #tempFieldAssetID tf on t.AssetID = tf.AssetID where t.AssetID is not null;
update t set t.ActionName = 'Update' from #tempInsertedAsset t inner join #tempDeleted F on t.AssetID = F.AssetID where t.AssetID is not null;
select F.AssetID, F.FieldTypeID, FT.FriendlyName, f.FormattedValue into #TempFieldData from #tempInsertedAsset I inner join Field F on f.AssetID = I.AssetID inner join fieldtype ft on f.fieldtypeid = ft.id
create clustered index ci_TempFieldData on #TempFieldData(AssetID);
INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select I.ActionName, a.Object, coalesce(a.ObjectID,0), ( select I2.ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, f.FriendlyName as [Name], f.FormattedValue as [Value] from #TempFieldData f where f.AssetID = I.AssetID for json path ) as Fields from #tempInsertedAsset I2 where I2.AssetID = I.AssetID group by I2.AssetID, I2.ActionName, coalesce(@resourceId, i2.UpdatedBy, 0) for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(I.AssetID,0) as [AssetID] from #tempInsertedAsset I inner join asset a on a.ID = i.AssetID inner join AssetType Att on Att.ID = A.AssetTypeID where Att.Class != 12 and I.[AssetID] Is not null;
-- remove temporary tables drop table if exists #tempInsertedAsset; drop table if exists #TempFieldData; drop table if exists #tempFieldAssetID;
end
-- handle relationships both sides need audit entries if exists(select 1 from #tempInserted i where i.[IntersectID] is not null) begin
if (select count(distinct updatedby) from #tempInserted where IntersectID is not null) > 1 begin set @resourceid = 0 end
drop table if exists #tempInsertedIntersect;
select t.IntersectID, Max(t.ActionName) ActionName, max(t.UpdatedBy) UpdatedBy into #tempInsertedIntersect from #tempInserted t where t.IntersectID is not null group by t.IntersectID;
drop table if exists #tempFieldIntersectID;
select t.IntersectID into #tempFieldIntersectID from #tempInsertedIntersect t inner join Field F on F.IntersectID = t.IntersectID where F.IntersectID is not null and not exists(select 1 from #tempInserted ti where ti.IntersectID = F.IntersectID and ti.id = F.id) group by t.IntersectID;
update t set t.ActionName = 'Update' from #tempInsertedIntersect t inner join #tempFieldIntersectID tf on t.IntersectID = tf.IntersectID where t.IntersectID is not null;
update t set t.ActionName = 'Update' from #tempInsertedIntersect t inner join #tempDeleted F on t.IntersectID = F.IntersectID where t.IntersectID is not null;
drop table if exists #tempinterdata;
with rsdata as ( select i.IntersectID,inter.ObjectAssetID,inter.SubjectAssetID, i.ActionName, i.UpdatedBy from #tempInsertedIntersect i inner join [intersect] inter on(i.IntersectID = inter.ID) where i.[IntersectID] is not null) select distinct a.* into #tempinterdata from ( select IntersectID, ActionName, UpdatedBy, SubjectAssetID AssetID from rsdata union all select IntersectID, ActionName, UpdatedBy, ObjectAssetID AssetID from rsdata) a;
create clustered index idx_tempinterdata on #tempinterdata(IntersectID,AssetID)
drop table if exists #TempFieldDataIntersect;
select F.IntersectID, F.FieldTypeID, FT.FriendlyName, f.FormattedValue into #TempFieldDataIntersect from #tempInsertedIntersect I inner join Field F on f.IntersectID = I.IntersectID inner join fieldtype ft on f.fieldtypeid = ft.id ;
create clustered index ci_TempFieldDataIntersect on #TempFieldDataIntersect(IntersectID);
-- object side of relationship INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select i.ActionName, 'Intersect', i.IntersectID ID, ( select i2.ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, f.FriendlyName as [Name], f.FormattedValue as [Value] from #TempFieldDataIntersect f where f.IntersectID = i2.IntersectID for json path ) as Fields from #tempinterdata i2 where i2.IntersectID = i.IntersectID group by i2.IntersectID,i2.ActionName, coalesce(@resourceId, i2.UpdatedBy, 0) for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(a.ID,0) as [AssetID] from #tempinterdata i inner join asset a on(a.ID = i.AssetID);
drop table if exists #tempInsertedIntersect; drop table if exists #TempFieldDataIntersect; drop table if exists #tempinterdata; drop table if exists #tempFieldIntersectID;
end drop table if exists #tempInserted; drop table if exists #tempDeleted;

changeSet.rollback:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterUpsert] ON [dbo].[Field] FOR INSERT, UPDATE AS SET NOCOUNT ON;
-- formatted value logic only needs to run in cases where value is not null if exists( select 1 from inserted where [value] is not null or [formattedvalue] is not null) begin
if exists (select 1 from inserted where AssetID IS NOT NULL) begin UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and (F.AssetID IS NOT NULL AND F.AssetID = T.AssetID) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID; end
if exists (select 1 from inserted where IntersectID IS NOT NULL) begin UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and (F.IntersectID IS NOT NULL AND F.IntersectID = T.IntersectID) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID; end
if exists (select 1 from inserted where IssueID IS NOT NULL) begin UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and (F.IssueID IS NOT NULL AND F.IssueID = T.IssueID) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID; end
drop table if exists #insertedFields; create table #insertedFields (ObjectType varchar(250), ObjectID int); create clustered index IX_TempInsertedFields ON #insertedFields (ObjectType, ObjectID);
drop table if exists #distinctFieldTypeIDs; create table #distinctFieldTypeIDs (ID int); create clustered index IX_distinctFieldTypeIDs ON #distinctFieldTypeIDs (ID);
insert into #distinctFieldTypeIDs select distinct I.FieldTypeID from inserted i where exists (select 1 from deleted d where d.id = i.id);
insert into #insertedFields select distinct replace(AT.[Object],'Type',''), AT.ObjectID from #distinctFieldTypeIDs i inner join FieldType FT on FT.ID = i.ID inner join assettype AT on AT.ID = FT.AssetTypeID and FT.AssetTypeID is not Null union select 'Intersect', FT.IntersectTypeID from #distinctFieldTypeIDs i inner join FieldType FT on FT.ID = i.ID and FT.IntersectTypeID is not Null union select 'Issue', FT.IssueTypeID from #distinctFieldTypeIDs i inner join FieldType FT on FT.ID = i.ID and FT.IssueTypeID is not Null;
drop table if exists #lookupFieldTypes select distinct FT.ID into #lookupFieldTypes from #insertedFields SF inner join FieldType FT on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID
if exists( select top 1 1 from #lookupFieldTypes ) begin
UPDATE TF SET TF.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, TF.Value, FT.AllowMultipleValues) from Field TF inner join #lookupFieldTypes LFT ON LFT.ID = TF.FieldTypeID inner join FieldType FT on FT.ID = TF.FieldTypeID where TF.[Value] is not null; end end
-------------------------------------------- -- audit field value changes -------------------------------------------- Declare @ActionName varchar(20) = 'Add'; IF EXISTS(SELECT * FROM DELETED) BEGIN -- this is an update statement set @ActionName = 'Update'; END
INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, a.Object, coalesce(a.ObjectID,0), ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.AssetID = i.AssetID for json path ) as Fields from inserted i2 where i2.AssetID = i.AssetID group by AssetID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(i.AssetID,0) as [AssetID] from inserted i inner join asset a on a.ID = i.AssetID inner join AssetType Att on Att.ID = A.AssetTypeID where Att.Class != 12 and I.[AssetID] Is not null;
-- handle relationships both sides need audit entries if exists(select 1 from inserted i where i.[IntersectID] is not null) begin
drop table if exists #tempinterdata;
with rsdata as ( select IntersectID,inter.ObjectAssetID,inter.SubjectAssetID from inserted i inner join [intersect] inter on(i.IntersectID = inter.ID) where i.[IntersectID] is not null) select distinct a.* into #tempinterdata from ( select IntersectID, SubjectAssetID AssetID from rsdata union all select IntersectID, ObjectAssetID AssetID from rsdata) a;
create index idx_tempinterdata on #tempinterdata(IntersectID,AssetID)
-- object side of relationship INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select @ActionName, 'Intersect', i.IntersectID ID, ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.IntersectID = i.IntersectID for json path ) as Fields from inserted i2 where i2.IntersectID = i.IntersectID group by ObjectType, ObjectID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(a.ID,0) as [AssetID] from #tempinterdata i inner join asset a on(a.ID = i.AssetID);
end

changeSet.sql:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterDelete] ON [dbo].[Field] AFTER DELETE AS BEGIN -- SET NOCOUNT ON added to prevent extra result sets from -- interfering with SELECT statements. SET NOCOUNT ON;
drop table if exists #tempdeleted; drop table if exists #tempdeletedUQ; drop table if exists #tempdeletedUQFields;
select fieldtypeid, AssetID, IntersectID, IssueID, UpdatedBy into #tempdeleted from deleted;
create index idx_tempdeleted on #tempdeleted(fieldtypeid) INCLUDE([AssetID],[IntersectID],[IssueID]);
select distinct AssetID, IntersectID, IssueID into #tempdeletedUQ from #tempdeleted;
select distinct fieldtypeid, AssetID, IntersectID, IssueID, UpdatedBy into #tempdeletedUQFields from #tempdeleted;
create index idx_tempdeletedUQFields on #tempdeletedUQFields(fieldtypeid) INCLUDE([AssetID],[IntersectID],[IssueID]);;
declare @resourceId int = null
if (select count(distinct updatedby) from #tempdeletedUQFields) > 1 begin set @resourceid = 0 end
-- audit field delete Asset INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Delete', A.Object, A.ObjectID, (select 'Delete' as Action, A.Object as ActionObject, A.ObjectID as ActionObjectID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select (select d3.FieldTypeID, coalesce(ft.FriendlyName, '<deleted field type>') as [Name], '' as [Value] from #tempdeleted d3 left join fieldtype ft on d3.fieldtypeid = ft.id where d3.AssetID = d.AssetID for xml path('Field'), TYPE ) for xml path('FieldInfo'), TYPE ) from #tempdeletedUQFields i2 where i2.AssetID = d.AssetID group by AssetID, coalesce(@resourceId, i2.UpdatedBy, 0) for xml path('fields')) , coalesce(d.AssetID,0) as [AssetID] from #tempdeletedUQ d inner join asset A on d.AssetID=A.ID;
-- audit field delete intersect INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Delete', 'Intersect', I.ID, (select 'Delete' as Action, 'Intersect' ActionObject, I.ID ActionObjectID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select (select d3.FieldTypeID, coalesce(ft.FriendlyName, '<deleted field type>') as [Name], '' as [Value] from #tempdeleted d3 left join fieldtype ft on d3.fieldtypeid = ft.id where d3.intersectID = d.intersectID for xml path('Field'), TYPE ) for xml path('FieldInfo'), TYPE ) from #tempdeletedUQFields i2 where i2.intersectID = d.intersectID group by intersectID, coalesce(@resourceId, i2.UpdatedBy, 0) for xml path('fields')) , coalesce(d.AssetID,0) as [AssetID] from #tempdeletedUQ d inner join [Intersect] I on d.IntersectID=I.ID;
-- audit field delete issue INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Delete', 'Issue', I.ID, (select 'Delete' as Action, 'Issue' ActionObject, I.ID ActionObjectID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select (select d3.FieldTypeID, coalesce(ft.FriendlyName, '<deleted field type>') as [Name], '' as [Value] from #tempdeleted d3 left join fieldtype ft on d3.fieldtypeid = ft.id where d3.IssueID = d.IssueID for xml path('Field'), TYPE ) for xml path('FieldInfo'), TYPE ) from #tempdeletedUQFields i2 where i2.IssueID = d.IssueID group by IssueID, coalesce(@resourceId, i2.UpdatedBy, 0) for xml path('fields')) , coalesce(d.AssetID,0) as [AssetID] from #tempdeletedUQ d inner join issue I on d.IssueID=I.ID; END
